code:
// composer.json
{
    "autoload": {
        "psr-4": { "App\\": "src/" }
    }
}
// then run:  composer dump-autoload

<?php
// src/Services/PriceService.php
namespace App\Services;

class PriceService
{
    public function withGst(float $p): float { return $p * 1.18; }
}

<?php
// index.php
require __DIR__ . "/vendor/autoload.php";
use App\Services\PriceService;

echo (new PriceService())->withGst(100);   // 118
